        for bj,(c0,c1) in enumerate(zip(cs[:-1],cs[1:])):
            s=g[r0:r1,c0:c1]
            mask=(s!=dom)&(s!=sep)
            pos=tuple(map(int,np.argwhere(mask)))
            seen=set(); comps=[]
            for p in pos:
                if p not in seen:
                    stack=[p]; comp=set(); seen.add(p)
                    while stack:
                        x,y=stack.pop()
                        if (x,y) in comp: continue
                        comp.add((x,y))
                        for dx in (-1,0,1):
                            for dy in (-1,0,1):
                                a,b=(x+dx,y+dy)
