            bbs=tuple(sorted([[min(p[0] for p in c),max(p[0] for p in c),min(p[1] for p in c),max(p[1] for p in c)] for c in comps]))
            rows.append({'block':name,bi,bj,'val':O[name][:bi if False else 0].tolist()} ) 
